SELECT ROUND(
         ST_Area_Spheroid(
           ST_ConvexHull(ST_Collect(list(geometry)))
         ) / 1000000.0,
         2
       ) AS hull_area_sq_km
FROM lisbon_places
WHERE taxonomy."primary" = 'historic_site'
  AND operating_status = 'open';

SELECT ROUND(
         ST_Perimeter_Spheroid(
           ST_ConvexHull(ST_Collect(list(geometry)))
         ) / 1000.0,
         2
       ) AS boundary_km
FROM lisbon_places
WHERE basic_category = 'restaurant'
  AND operating_status = 'open';
